text:
Caveman mode: **full**

---

Three parts: class component, fallback UI, error log.

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ──────────────────────────────────────────────────────────────────
interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

// ── Logger ─────────────────────────────────────────────────────────────────
function logError(error: Error, info: ErrorInfo): void {
  console.error("[ErrorBoundary]", {
    message: error.message,
    stack: error.stack,
    componentStack: info.componentStack,
    timestamp: new Date().toISOString(),
  });

  // Swap for real service: Sentry, Datadog, etc.
  // reportingService.captureException(error, { extra: info });
}

// ── Default Fallback UI ────────────────────────────────────────────────────
function DefaultFallback({
  error,
  onRetry,
}: {
  error: Error;
  onRetry: () => void;
}) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={onRetry} style={styles.button}>
        Retry
      </button>
    </div>
  );
}

// ── Error Boundary ─────────────────────────────────────────────────────────
export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    // Triggers fallback render
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.setState({ errorInfo: info });
    logError(error, info);
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // Custom fallback wins if provided
    return fallback ? fallback(error, this.reset) : (
      <DefaultFallback error={error} onRetry={this.reset} />
    );
  }
}

// ── Styles ─────────────────────────────────────────────────────────────────
const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title: { color: "#b91c1c", marginTop: 0 },
  message: {
    background: "#fee2e2",
    padding: "0.75rem",
    borderRadius: "4px",
    fontSize: "0.85rem",
    overflowX: "auto" as const,
    whiteSpace: "pre-wrap" as const,
  },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "0.95rem",
  },
} as const;
```

Usage — three patterns:

```tsx
// 1. Default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// 2. Custom fallback UI
<ErrorBoundary fallback={(err, retry) => (
  <div>
    <p>Oops: {err.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>

// 3. Hook into external error service
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

---

Key decisions:

- `getDerivedStateFromError` → trigger fallback (static, no side effects)
- `componentDidCatch` → log + notify (side effects live here)
- `reset()` clear both `error` + `errorInfo` — stale info cause ghost errors if only one cleared
- Custom `fallback` prop = render prop pattern, full control without subclassing
- Must be class component — hooks no catch render errors yet
